"""以 PCCES 匯出的預算書為底稿，改詳細表葉項的數量或單價、或單價分析組成列的數量或單價，重算後另存
（M3 寫入工具 `pcces_write_budget` 用）。

只動得到依據的欄位：葉項的數量、單價、複價，改到的母項與受影響的小計列（含總計列）的單價＝複價，
`TotalAmount`、`TotalAmountChinese`。母項不含小計子項；小計列照 `etender.py` 模組說明的規則重算（PCX-003）。
改單價分析的組成（`ItemEdit.component`）時，另外重算那個分析的組成複價、% 類、分析單價（`analysis.py` 的規則），
詳細表每一列用到它的葉項單價跟著換；一般工料（itemKind=general）的單價全案共用，所有分析裡同代碼的列與
資源統計的單價一起改，變動單價工料（variablePrice）只改那一個分析。
公式項、資源統計的數量與複價、人機料雜比例、八大宗材、編碼正確率這些 PCCES 重新總計時才算的值照抄底稿，
在 `EditResult.not_updated` 逐條講明，交給 PCCES 重新總計。
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal, InvalidOperation
from pathlib import Path

from . import analysis as an
from .document import ETenderDocument, Item, parse_document
from .etender import (
    SUBTOTAL_KIND, check_consistency, item_path, leaf_amount, mathml_sum_refs, parse_etender, preceding_sum, round_price,
)
from .writer import write_document

# variablePrice＝變動單價項（實案 1103 列）：沒有單價分析，數量×單價跟 general 同一條（實案 1103/1103 列對得上）
EDITABLE_KINDS = ("analysis", "general", "variablePrice")
COMPONENT_KINDS = (an.GENERAL_KIND, an.VARIABLE_KIND)
FORMULA_KIND = "formula"
# 交換標準：Quantity、Price 是 decimal_20_4（PCCES 內附 xsd），ContractTitle 200 字、TotalAmountChinese 40 字
MAX_DIGITS = 20
# 單價：xsd 准 4 位，但 PCCES 匯出檔裡詳細表單價最多只看過 2 位（Class01 的 -243.58、1999.3），超過的寫法沒有依據
PRICE_MAX_DECIMALS = 2
TITLE_MAX = 200
CHINESE_MAX = 40
LIST_LIMIT = 30


class EditError(ValueError):
    """這個改法不被允許；訊息直接給模型看，要講得出下一步。

    `brief`：讀取工具標「這一列能不能改」時用的短理由（`item_view.py` 拿同一套檢查試改一次），沒給就是整句訊息。
    """

    def __init__(self, message: str, brief: str | None = None):
        super().__init__(message)
        self.brief = brief or message


def read_hint(path: str) -> str:
    """寫入工具的錯誤訊息指回讀取工具：模型先看組成與哪些列能改，不必靠錯誤訊息猜。"""
    return f"要先看這一項的單價分析組成與哪些列能改，叫 pcces_read_budget 帶 item=\"{path}\""


