# ---------- 數字 ----------


def fmt_decimal(d: Decimal) -> str:
    """寫進 XML 的數字照 PCCES 匯出檔：不補尾零、不用科學記號（1680、683.78、-243.58）。"""
    if d == 0:
        return "0"  # 0 × 負單價會得到 -0
    return format(d.normalize(), "f")


def _decimals(d: Decimal) -> int:
    return max(0, -d.normalize().as_tuple().exponent)


def _digits(d: Decimal) -> int:
    t = d.normalize().as_tuple()
    return max(len(t.digits), -t.exponent) if t.exponent < 0 else len(t.digits) + t.exponent


def to_decimal(value: object, what: str) -> Decimal:
    try:
        d = Decimal(repr(value) if isinstance(value, float) else str(value))
    except InvalidOperation as exc:
        raise EditError(f"{what} 不是數字：{value!r}") from exc
    if not d.is_finite():
        raise EditError(f"{what} 不是有限的數字：{value!r}")
    return d


_CN_DIGITS = "零壹貳參肆伍陸柒捌玖"
_CN_SMALL = ("", "拾", "佰", "仟")
_CN_BIG = ("", "萬", "億", "兆")


def amount_chinese(n: int) -> str:
    """總價國字大寫，格式照 PCCES 匯出檔（46105141 → 新台幣肆仟陸佰壹拾萬伍仟壹佰肆拾壹元整）。

    兩份示範案例驗過「參」「壹拾」「萬位前補零」（7031678 → 柒佰零參萬…）；整組為零、跨萬位補零的寫法
    是照一般大寫規則推的，PCCES 沒有樣本。
    """
    if n < 0:
        raise ValueError("負的總價沒有國字大寫的依據")
    if n == 0:
        return "新台幣零元整"
    groups: list[int] = []
    while n:
        groups.append(n % 10000)
        n //= 10000
    if len(groups) > len(_CN_BIG):
        raise ValueError("總價超過兆位")
    out: list[str] = []
    pending_zero = False
    for gi in range(len(groups) - 1, -1, -1):
        g = groups[gi]
        if g == 0:
            pending_zero = bool(out)
            continue
        if out and (pending_zero or g < 1000):
            out.append("零")
        pending_zero = False
        s, zero = "", False
        for pos in range(3, -1, -1):
            d = g // 10**pos % 10
            if d == 0:
                zero = bool(s)
            else:
                if zero:
                    s += "零"
                    zero = False
                s += _CN_DIGITS[d] + _CN_SMALL[pos]
        out.append(s + _CN_BIG[gi])
    return "新台幣" + "".join(out) + "元整"


# ---------- 項次路徑 ----------


def _no(it: Item) -> str:
    return it.attrs.get("itemNo", "").strip()


def _name(it: Item) -> str:
    return (it.value("Description", "zh-TW") or "").strip()


def _kind(it: Item) -> str:
    return it.attrs.get("itemKind", "").strip()


def normalize_path(path: str) -> str:
    return ".".join(p.strip() for p in path.replace("．", ".").split("."))


@dataclass
class _Index:
    """詳細表每列的項次路徑（`etender.item_path`：itemNo 已是完整項次就直接用，否則用「.」接上層）。"""

    path_of: dict[int, str]
    by_path: dict[str, list[tuple[list[Item], Item]]]
    parent_path: dict[int, str]

    def path(self, it: Item) -> str:
        return self.path_of[id(it)]


def _index(doc: ETenderDocument) -> _Index:
    idx = _Index({}, {}, {})

    def walk(items: list[Item], chain: list[Item], parent_path: str, parent_no: str) -> None:
        for it in items:
            path = item_path(parent_path, parent_no, _no(it))
            idx.path_of[id(it)] = path
            idx.parent_path[id(it)] = parent_path
            if path:
                idx.by_path.setdefault(path, []).append((chain, it))
            walk(it.children, chain + [it], path, _no(it))

    walk(doc.detail_list.items, [], "", "")
    return idx


def _label(idx: _Index, it: Item) -> str:
    """錯誤訊息與回報用：有項次寫項次＋名稱，小計列沒有項次就寫在哪一層底下。"""
    if idx.path(it):
        return f"{idx.path(it)} {_name(it)}"
    return f"{idx.parent_path[id(it)] or '頂層'} 底下的「{_name(it)}」"


def _analysis_codes(doc: ETenderDocument) -> set[str]:
    if doc.cost_breakdown_list is None:
        return set()
    return {w.attrs.get("itemCode", "").strip() for w in doc.cost_breakdown_list.items} - {""}


def _has_analysis(it: Item, codes: set[str]) -> bool:
    return _kind(it) == "analysis" or it.attrs.get("refItemCode", "").strip() in codes


def _hint(it: Item, codes: set[str]) -> str:
    if it.children:
        return "母項"
    k = _kind(it)
    if k == FORMULA_KIND or it.get("mml:math") is not None:
        return "公式項，不能改"
    if k not in EDITABLE_KINDS:
        return f"itemKind={k or '（空）'}，不支援"
    return "有單價分析，可改數量，單價用 component 改組成" if _has_analysis(it, codes) else "可改數量、單價"


def _listing(entries: list[tuple[list[Item], Item]], codes: set[str], idx: _Index) -> str:
    rows = [f"{idx.path(it)} {_name(it)}（{_hint(it, codes)}）" for _, it in entries[:LIST_LIMIT]]
    more = f"……另有 {len(entries) - LIST_LIMIT} 項" if len(entries) > LIST_LIMIT else ""
    return "；".join(rows) + more


def _leaves(chain: list[Item], it: Item) -> list[tuple[list[Item], Item]]:
    out: list[tuple[list[Item], Item]] = []
    for c in it.children:
        if not _no(c):
            continue
        if c.children:
            out += _leaves(chain + [it], c)
        else:
            out.append((chain + [it], c))
    return out


def _ambiguous(path: str, hits: list[tuple[list[Item], Item]], codes: set[str], idx: _Index) -> EditError:
    return EditError(
        f"項次「{path}」不唯一：詳細表有 {len(hits)} 列都是這個項次（itemNo 重複，或每層只寫一段與寫完整項次兩種寫法混用），"
        f"這份底稿不能用項次指定這一列。候選：{_listing(hits, codes, idx)}"
    )


def resolve(doc: ETenderDocument, path: str, idx: _Index | None = None) -> tuple[list[Item], Item]:
    """用項次路徑（例 壹.一.2）找詳細表的項目，回傳（上層鏈, 項目）；找不到就列出最近那一層有哪些項次。"""
    idx = idx or _index(doc)
    norm = normalize_path(path)
    parts = norm.split(".")
    codes = _analysis_codes(doc)
    tops = [([], i) for i in doc.detail_list.items if _no(i)]
    if not path.strip() or any(not p for p in parts):
        raise EditError(
            f"項次路徑「{path}」格式不對，要寫成 pcces_read_budget 顯示的項次，例如 壹.一.2；"
            f"每層只寫一段的預算書就把各層用「.」串起來。頂層有：{_listing(tops, codes, idx)}"
        )
    hits = idx.by_path.get(norm, [])
    if len(hits) > 1:
        raise _ambiguous(norm, hits, codes, idx)
    if hits:
        return hits[0]
    # 從最長的上層往回找，指出是在哪一層斷掉
    for n in range(len(parts) - 1, 0, -1):
        pre = ".".join(parts[:n])
        up = idx.by_path.get(pre, [])
        if len(up) > 1:
            raise _ambiguous(pre, up, codes, idx)
        if up:
            chain, it = up[0]
            if not it.children:
                raise EditError(f"找不到項次「{path}」：{pre} {_name(it)} 是葉項，底下沒有子項")
            here = [(chain + [it], c) for c in it.children if _no(c)]
            rest = ".".join(parts[n:])
            raise EditError(f"找不到項次「{path}」：{pre} 底下沒有「{rest}」。{pre} 底下有：{_listing(here, codes, idx)}")
    raise EditError(f"找不到項次「{path}」：頂層 底下沒有「{parts[0]}」。頂層 底下有：{_listing(tops, codes, idx)}")


# ---------- 改值 ----------


def _check_number(d: Decimal, what: str, max_decimals: int, why: str) -> None:
    if _decimals(d) > max_decimals:
        raise EditError(f"{what} {fmt_decimal(d)} 的小數超過 {max_decimals} 位（{why}），請先自己進位再給")
    if _digits(d) > MAX_DIGITS:
        raise EditError(f"{what} {fmt_decimal(d)} 超過交換標準的 {MAX_DIGITS} 位數")


def _node(it: Item, tag: str, path: str):
    n = it.get(tag)
    if n is None or not (n.text or "").strip():
        raise EditError(f"{path} {_name(it)} 沒有 {tag}，這份底稿不能用這支工具改", brief=f"這一列沒有 {tag}")
    return n


def _set_sum(it: Item, label: str, total: Decimal) -> Decimal | None:
    """母項與小計列：數量 1、單價＝複價，改成新的加總。示範案例與實案的母項、小計列全是這個樣子。"""
    q, p, a = it.decimal("Quantity"), it.decimal("Price"), it.decimal("Amount")
    if q != 1 or p != a:
        raise EditError(
            f"{label} 的數量不是 1 或單價不等於複價，PCCES 怎麼重算這種列沒有依據，"
            "這支工具不處理；請在 PCCES 裡改。"
        )
    _node(it, "Price", label).text = fmt_decimal(total)
    _node(it, "Amount", label).text = fmt_decimal(total)
    return a


class _Unknown(Exception):
    """這一列小計照規則算不出來（公式看不懂、引用對不到、循環）；訊息是原因。"""


@dataclass
class _Subtotal:
    item: Item
    siblings: list[Item]
    index: int
    refs: list[tuple[int, str]] | None
    error: str


def _mml_tag(n) -> str:
    return n.tag[4:] if n.tag.startswith("mml:") else n.tag


def _subtotals(doc: ETenderDocument) -> list[_Subtotal]:
    out: list[_Subtotal] = []

    def walk(items: list[Item]) -> None:
        for i, it in enumerate(items):
            if _kind(it) == SUBTOTAL_KIND:
                refs, error = None, ""
                math = it.get("mml:math")
                if math is not None:
                    try:
                        refs = mathml_sum_refs(math, _mml_tag, lambda n: n.children, lambda n: n.text)
                    except ValueError as exc:
                        error = f"小計公式{exc}"
                out.append(_Subtotal(it, items, i, refs, error))
            walk(it.children)

    walk(doc.detail_list.items)
    return out


def _evaluate(subs: list[_Subtotal], by_key: dict[str, list[Item]]) -> dict[int, Decimal | str]:
    """每列小計照規則（`etender.py` 模組說明）算出的值；算不出來的放原因字串。用的是模型裡現在的複價。"""
    info = {id(s.item): s for s in subs}
    memo: dict[int, Decimal | str] = {}
    visiting: set[int] = set()

    def amount(it: Item) -> Decimal:
        return value(it) if id(it) in info else it.decimal("Amount") or Decimal(0)

    def value(it: Item) -> Decimal:
        got = memo.get(id(it))
        if isinstance(got, Decimal):
            return got
        if isinstance(got, str):
            raise _Unknown(got)
        if id(it) in visiting:
            raise _Unknown("小計公式循環引用")
        visiting.add(id(it))
        try:
            s = info[id(it)]
            if s.error:
                raise _Unknown(s.error)
            if s.refs is None:
                v = preceding_sum(s.siblings, s.index, lambda x: x.decimal("Amount"), lambda x: _kind(x) == SUBTOTAL_KIND)
            else:
                v = Decimal(0)
                for sign, key in s.refs:
                    hits = by_key.get(key, [])
                    if len(hits) != 1:
                        why = "沒有這一列" if not hits else "有好幾列用這個號碼"
                        raise _Unknown(f"小計公式引用 itemKey {key}，詳細表{why}")
                    v += sign * amount(hits[0])
        except _Unknown as exc:
            memo[id(it)] = str(exc)
            raise
        finally:
            visiting.discard(id(it))
        memo[id(it)] = v
        return v

    out: dict[int, Decimal | str] = {}
    for s in subs:
        try:
            out[id(s.item)] = value(s.item)
        except _Unknown as exc:
            out[id(s.item)] = str(exc)
    return out


def _formula_items(doc: ETenderDocument, idx: _Index) -> list[str]:
    # 小計列的 MathML 是加總，這支工具會重算，不列在照抄的公式項裡
    return [
        _label(idx, it)
        for _, it in doc.detail_list.iter_items()
        if _kind(it) != SUBTOTAL_KIND and (_kind(it) == FORMULA_KIND or it.get("mml:math") is not None)
    ]


def _not_updated(doc: ETenderDocument, formulas: list[str], chinese_done: bool, stale: list[str],
                 analyses: list[AnalysisChange] | None = None, resources: list[ResourceChange] | None = None) -> list[str]:
    notes: list[str] = []
    if formulas:
        notes.append(f"公式項 {len(formulas)} 項照抄底稿、沒有重算：{'、'.join(formulas)}")
    if stale:
        notes.append(f"小計列 {len(stale)} 列照規則算不出來，照抄底稿、沒有重算：{'；'.join(stale)}")
    if analyses:
        notes.append(
            "單價分析與詳細表那幾列的人機料雜比例（LabourRatio、EquipmentRatio、MaterialRatio、MiscellaneaRatio）照抄底稿："
            "PCCES 的算法沒推出來（照各列複價×比例÷單價算，ArchEx001 只對得上 10/22 個分析）"
        )
    if doc.resource_list is not None:
        if resources:
            notes.append(f"資源統計（ResourceList）只改了一般工料的單價（{'、'.join(r.code for r in resources)}），"
                         "工料數量與複價照抄底稿")
        else:
            notes.append("資源統計（ResourceList）照抄底稿：工料數量與複價沒有跟著改")
    if any(n.tag == "MaterialData" for n in doc.extensions):
        notes.append("八大宗材（MaterialData）照抄底稿")
    if any(doc.tender_information.find(t) is not None for t in ("CorrectRatio", "WeightCorrectRatio", "WeightFitRatio")):
        notes.append("編碼正確率與符合率（CorrectRatio 等）照抄底稿：加權值跟金額有關，PCCES 的算法沒推出來")
    info = next((n for n in doc.extensions if n.tag == "InfoSummary"), None)
    if info is not None and "CostPerUnit" in (info.text or ""):
        notes.append("InfoSummary 的 CostPerUnit（單位造價）照抄底稿：算法查不到依據")
    extra = [c.tag for c in doc.grand_total.children if c.tag not in ("TotalAmount", "TotalAmountChinese")]
    if extra:
        notes.append(f"GrandTotalInformation 的 {'、'.join(extra)} 照抄底稿")
    if not chinese_done:
        notes.append("TotalAmountChinese（總價國字）照抄底稿：總價有小數或是負數，國字寫法沒有依據")
    return notes


_COMP_KIND_LABEL = {
    an.GENERAL_KIND: "一般工料，單價全案共用",
    an.VARIABLE_KIND: "變動單價，只屬這個分析",
    an.PCT_KIND: "% 類",
    an.ANALYSIS_KIND: "巢狀分析",
}


def _component_rows(w: Item) -> str:
    """錯誤訊息用：列出一個分析的每一列組成。"""
    rows = []
    for c in w.children:
        k = an.kind(c)
        what = _COMP_KIND_LABEL.get(k, f"itemKind={k or '（空）'}")
        if k == an.PCT_KIND:
            what += f" {(c.value('Percent') or '').strip()}%"
        rows.append(f"{an.code(c)} {an.name(c)}（{what}，數量 {(c.value('Quantity') or '').strip()}，"
                    f"單價 {(c.value('Price') or '').strip()}）")
    return "；".join(rows)


def _example(path: str, w: Item) -> str:
    row = next((c for c in w.children if an.kind(c) in COMPONENT_KINDS), None)
    if row is None:
        return ""
    return f'，例如 {{"item": "{path}", "component": "{an.code(row)}", "quantity": {(row.value("Quantity") or "").strip()}}}'


def _copies(doc: ETenderDocument, acode: str) -> list[Item]:
    """CostBreakdownList 頂層裡這個分析的每一份（同一分析被兩列詳細表用到，PCCES 就輸出兩份）。"""
    if doc.cost_breakdown_list is None:
        return []
    return [w for w in doc.cost_breakdown_list.items if an.code(w) == acode]


@dataclass
class _CompPlan:
    path: str
    acode: str
    index: int  # 組成列在分析裡的位置（每一份都一樣，`analysis.same_analysis` 驗過）
    code: str
    kind: str
    quantity: Decimal | None
    price: Decimal | None


def _plan_component(doc: ETenderDocument, e: ItemEdit, idx: _Index, codes: set[str], d: an.Digits) -> _CompPlan:
    path = normalize_path(e.path)
    chain, it = resolve(doc, e.path, idx)
    nm = _name(it)
    if it.children:
        leaves = [(c, x) for c, x in _leaves(chain, it) if _has_analysis(x, codes)]
        raise EditError(f"{path} {nm} 是母項，沒有單價分析。component 要配有單價分析的葉項"
                        + (f"，底下有：{_listing(leaves, codes, idx)}" if leaves else "，它底下沒有"))
    acode = it.attrs.get("refItemCode", "").strip()
    if not _has_analysis(it, codes):
        raise EditError(f"{path} {nm} 沒有單價分析，component 只用在有單價分析的工項；"
                        "這一項的數量、單價直接給 quantity、price，不要帶 component")
    if _kind(it) != "analysis":
        raise EditError(f"{path} {nm} 的 itemKind 是「{_kind(it)}」，但工項代碼 {acode} 在單價分析表裡有；"
                        "這種寫法沒有樣本，PCCES 怎麼連動不知道，這支工具不改，請在 PCCES 裡改",
                        brief=f"這一項的 itemKind 是「{_kind(it)}」不是 analysis，卻在單價分析表裡有，沒有樣本")
    copies = _copies(doc, acode)
    if not copies:
        raise EditError(f"{path} {nm} 標成有單價分析，但底稿的單價分析表（CostBreakdownList）沒有工項代碼 {acode}",
                        brief=f"單價分析表沒有工項代碼 {acode}")
    w = copies[0]
    want = (e.component or "").strip().upper()
    if not want:
        raise EditError(f"component 是空的：寫單價分析組成列的工料代碼。{path} 的組成有：{_component_rows(w)}。"
                        f"{read_hint(path)}")
    hits = [(i, c) for i, c in enumerate(w.children) if an.code(c).upper() == want]
    if not hits:
        raise EditError(f"{path} {nm} 的單價分析（{acode}）沒有工料代碼「{e.component}」的組成列。"
                        f"這個分析的組成有：{_component_rows(w)}。{read_hint(path)}")
    if len(hits) > 1:
        cands = "；".join(
            f"第 {i + 1} 列 {an.name(c)}（數量 {(c.value('Quantity') or '').strip()}，單價 {(c.value('Price') or '').strip()}，"
            f"複價 {(c.value('Amount') or '').strip()}）" for i, c in hits
        )
        raise EditError(f"{path} {nm} 的單價分析（{acode}）裡工料代碼 {want} 有 {len(hits)} 列，component 分不出要改哪一列，"
                        f"這支工具不改；請在 PCCES 裡改。候選：{cands}",
                        brief=f"這個分析裡同代碼有 {len(hits)} 列（第 {'、'.join(str(i + 1) for i, _ in hits)} 列），"
                              "component 分不出是哪一列")
    i, row = hits[0]
    k = an.kind(row)
    label = f"{path} {nm} 的組成 {an.code(row)} {an.name(row)}"
    if k == an.PCT_KIND:
        raise EditError(
            f"{label} 是 % 類（Percent {(row.value('Percent') or '').strip()}%），單價＝複價由其他各列與費率算出來，不能直接改。"
            "費率是同一個工料代碼全案共用（資料庫 budProjMrsA.rate），PCCES 改費率怎麼連動沒有樣本，這支工具不改費率，"
            "請在 PCCES 裡改。要動這個分析的單價，改其他組成列的數量或單價",
            brief="% 類，複價由其他各列合計與費率算出來；費率全案共用，工具不改",
        )
    if k == an.ANALYSIS_KIND:
        raise EditError(f"{label} 是巢狀分析（子分析），單價由它自己的組成算出來；"
                        "改巢狀分析沒有 PCCES 改值前後的樣本，這支工具不改，請在 PCCES 裡改",
                        brief="巢狀分析（子分析），單價由它自己的組成算出來，工具不改")
    if k not in COMPONENT_KINDS:
        raise EditError(f"{label} 的 itemKind 是「{k or '（空）'}」，這支工具只改一般工料（general）與變動單價工料（variablePrice）",
                        brief=f"itemKind 是「{k or '（空）'}」，工具只改一般工料與變動單價工料")
    if e.quantity is None and e.price is None:
        raise EditError(f"{label}：quantity 與 price 至少給一個")
    if e.quantity is not None:
        _check_number(e.quantity, f"{label} 的數量", d.quantity, f"單價分析 quantityDisplayDecimal={d.quantity}")
    if e.price is not None:
        _check_number(e.price, f"{label} 的單價", PRICE_MAX_DECIMALS, "PCCES 匯出檔的工料單價最多 2 位小數")
        p = row.get("Price")
        if p is not None and p.attrs.get("fixed") == "true":
            raise EditError(f"{label} 的單價是鎖定的（fixed=true），PCCES 對鎖定單價改價怎麼處理沒有樣本，"
                            "這支工具不改；請在 PCCES 裡改", brief="單價鎖定（fixed=true）")
    for tag in ("Quantity", "Price", "Amount"):
        _node(row, tag, f"{path} 的單價分析組成")
    return _CompPlan(path, acode, i, an.code(row), k, e.quantity, e.price)


@dataclass
class _Work:
    """一個要重算的單價分析：每一份、用到它的詳細表葉項、被哪些一般工料連帶。"""

    acode: str
    copies: list[Item]
    leaves: list[Item]
    targeted: bool = False
    linked_by: list[str] = field(default_factory=list)


def _plan_analyses(doc: ETenderDocument, plans: list[_CompPlan], d: an.Digits, idx: _Index) -> dict[str, _Work]:
    """找出這次會被重算的分析並逐一驗過：結構跟樣本一樣、底稿的值照規則重現得了，才准改。"""
    cbl = doc.cost_breakdown_list
    nested_codes: set[str] = set()  # 當成巢狀分析列出現過的分析
    inside_nested: set[str] = set()  # 出現在巢狀分析底下的工料

    def walk(w: Item, inside: bool) -> None:
        for c in w.children:
            if inside:
                inside_nested.add(an.code(c))
            if an.kind(c) == an.ANALYSIS_KIND:
                nested_codes.add(an.code(c))
                walk(c, True)

    for w in cbl.items:
        walk(w, False)
    leaves_of: dict[str, list[Item]] = {}
    for _, it in doc.detail_list.iter_items():
        if not it.children:
            leaves_of.setdefault(it.attrs.get("refItemCode", "").strip(), []).append(it)

    work: dict[str, _Work] = {}

    def add(acode: str, linked_by: str | None = None) -> None:
        wk = work.setdefault(acode, _Work(acode, _copies(doc, acode), leaves_of.get(acode, [])))
        if linked_by is None:
            wk.targeted = True
        elif linked_by not in wk.linked_by:
            wk.linked_by.append(linked_by)

    for p in plans:
        add(p.acode)
        if p.price is None or p.kind != an.GENERAL_KIND:
            continue
        if p.code in inside_nested:
            raise EditError(f"一般工料 {p.code} 的單價全案共用，它也出現在巢狀分析（子分析）裡；改了要一層層傳上去，"
                            "這種情形沒有 PCCES 改值前後的樣本，這支工具不改，請在 PCCES 裡改",
                            brief="這個一般工料也在巢狀分析（子分析）裡，改單價要一層層傳上去，沒有樣本")
        rows = [(w, c) for w in cbl.items for c in w.children if an.code(c) == p.code]
        if {an.kind(c) for _, c in rows} != {an.GENERAL_KIND}:
            raise EditError(f"工料 {p.code} 在不同分析裡的 itemKind 不一樣，樣本沒有這種寫法，這支工具不改；請在 PCCES 裡改",
                            brief="同代碼在不同分析裡的 itemKind 不一樣，沒有樣本")
        if len({c.decimal("Price") for _, c in rows}) > 1:
            raise EditError(f"一般工料 {p.code} 在各分析裡的單價不一樣，跟「一般工料單價全案共用」的樣本不符，這支工具不改；請在 PCCES 裡改",
                            brief="同代碼在各分析裡的單價不一樣，跟「一般工料單價全案共用」不符")
        direct = [it for it in leaves_of.get(p.code, []) if _kind(it) != "analysis"]
        if direct:
            raise EditError(f"詳細表也有工項代碼 {p.code} 的工項（{idx.path(direct[0])} {_name(direct[0])}），"
                            "PCCES 改工料單價時會不會連它一起改沒有樣本，這支工具不改；請在 PCCES 裡改",
                            brief=f"詳細表也有同代碼的工項（{idx.path(direct[0])}），會不會一起改沒有樣本")
        for w, _ in rows:
            add(an.code(w), linked_by=p.code)

    for wk in work.values():
        first = wk.copies[0]
        label = f"單價分析 {wk.acode} {an.name(first)}"
        # brief 帶分析代碼：一般工料改單價時擋下來的可能是被連帶的另一個分析
        if any(not an.same_analysis(first, w) for w in wk.copies[1:]):
            raise EditError(f"{label} 在單價分析表有 {len(wk.copies)} 份、內容不一樣，分不出是不是同一個分析，這支工具不改；請在 PCCES 裡改",
                            brief=f"單價分析 {wk.acode} 有 {len(wk.copies)} 份、內容不一樣")
        if wk.acode in nested_codes:
            raise EditError(f"{label} 也被別的分析當成巢狀分析（子分析）用，改了要一層層傳上去，"
                            "這種情形沒有 PCCES 改值前後的樣本，這支工具不改；請在 PCCES 裡改",
                            brief=f"單價分析 {wk.acode} 也被別的分析當成巢狀分析用，改了要一層層傳上去，沒有樣本")
        if any(_kind(it) != "analysis" for it in wk.leaves) or len(wk.leaves) != len(wk.copies):
            raise EditError(f"{label} 在單價分析表有 {len(wk.copies)} 份，詳細表用到它的葉項卻有 {len(wk.leaves)} 列"
                            "（或其中有不是 analysis 的列），對不起來，這支工具不改；請在 PCCES 裡改",
                            brief=f"單價分析 {wk.acode} 有 {len(wk.copies)} 份，詳細表用到它的葉項有 {len(wk.leaves)} 列，對不起來")
        bad = an.mismatches(first, d)
        if bad:
            used = "、".join(idx.path(it) or _name(it) for it in wk.leaves)
            raise EditError(f"{label}（詳細表 {used}）照單價分析規則重現不了底稿的值：{'；'.join(bad[:5])}。"
                            "這次的改動會重算它，規則對不上就沒有依據，這支工具不改；請在 PCCES 裡改",
                            brief=f"單價分析 {wk.acode} 照規則重現不了底稿的值（{bad[0]}）")
    return work


def _apply_components(doc: ETenderDocument, plans: list[_CompPlan], work: dict[str, _Work], d: an.Digits,
                      idx: _Index) -> tuple[list[AnalysisChange], list[ResourceChange], dict[int, Decimal]]:
    """改組成列、重算每個受影響的分析；回傳（分析變動, 資源統計變動, 詳細表葉項 id → 新單價）。"""
    snap = {a: ([(c.decimal("Quantity"), c.decimal("Price"), c.decimal("Amount")) for c in wk.copies[0].children],
                wk.copies[0].decimal("Price")) for a, wk in work.items()}
    resources: list[ResourceChange] = []
    for p in plans:
        for w in work[p.acode].copies:
            row = w.children[p.index]
            if p.quantity is not None:
                row.get("Quantity").text = fmt_decimal(p.quantity)
            if p.price is not None and p.kind == an.VARIABLE_KIND:
                row.get("Price").text = fmt_decimal(p.price)
        if p.price is not None and p.kind == an.GENERAL_KIND:
            for w in doc.cost_breakdown_list.items:
                for c in w.children:
                    if an.code(c) == p.code:
                        c.get("Price").text = fmt_decimal(p.price)
            for r in (doc.resource_list.items if doc.resource_list is not None else []):
                if r.tag == "WorkItem" and an.code(r) == p.code and r.get("Price") is not None:
                    resources.append(ResourceChange(p.code, an.name(r), r.decimal("Price"), p.price))
                    r.get("Price").text = fmt_decimal(p.price)

    changes: list[AnalysisChange] = []
    leaf_price: dict[int, Decimal] = {}
    for acode, wk in work.items():
        try:
            got = an.compute(wk.copies[0], d)
        except an.AnalysisRuleError as exc:
            raise EditError(f"單價分析 {acode} 改值後算不了：{exc}") from exc
        for w in wk.copies:
            for c, a in zip(w.children, got.amounts):
                if c.decimal("Amount") != a:
                    c.get("Amount").text = fmt_decimal(a)
                if an.kind(c) == an.PCT_KIND and c.decimal("Price") != a:
                    c.get("Price").text = fmt_decimal(a)
            if w.decimal("Price") != got.price:
                _node(w, "Price", f"單價分析 {acode}").text = fmt_decimal(got.price)
        rows_before, price_old = snap[acode]
        rows: list[ComponentChange] = []
        for c, (q0, p0, a0) in zip(wk.copies[0].children, rows_before):
            q1, p1, a1 = c.decimal("Quantity"), c.decimal("Price"), c.decimal("Amount")
            if (q0, p0, a0) != (q1, p1, a1):
                rows.append(ComponentChange(an.code(c), an.name(c), an.kind(c), q0, q1 if q1 != q0 else None,
                                            p0, p1 if p1 != p0 else None, a0, a1))
        changes.append(AnalysisChange(acode, an.name(wk.copies[0]), [idx.path(it) for it in wk.leaves],
                                      price_old, got.price, rows, not wk.targeted, list(wk.linked_by)))
        if got.price != price_old:
            for it in wk.leaves:
                leaf_price[id(it)] = got.price
    return changes, resources, leaf_price


@dataclass
class _LeafPlan:
    path: str
    chain: list[Item]
    item: Item
    quantity: Decimal | None = None
    price: Decimal | None = None
    via_analysis: bool = False


def _chains(doc: ETenderDocument) -> dict[int, list[Item]]:
    out: dict[int, list[Item]] = {}

    def walk(items: list[Item], chain: list[Item]) -> None:
        for it in items:
            out[id(it)] = chain
            walk(it.children, chain + [it])

    walk(doc.detail_list.items, [])
    return out


def apply_edits(doc: ETenderDocument, edits: list[ItemEdit]) -> EditResult:
    """就地改 `doc`。丟 EditError 時 `doc` 可能已改一半，呼叫端要整份丟掉、不能拿去寫。"""
    if not edits:
        raise EditError("edits 是空的：至少給一筆，例如 [{\"item\": \"壹.一.2\", \"quantity\": 100}]")
    dl = doc.detail_list
    q_dec = int(dl.attrs.get("quantityDisplayDecimal", "0") or 0)
    p_dec = int(dl.attrs.get("unitPriceDisplayDecimal", "0") or 0)
    a_dec = int(dl.attrs.get("itemAmountDisplayDecimal", "0") or 0)
    codes = _analysis_codes(doc)
    idx = _index(doc)

    # 先全部驗過再動手，任一筆不合就整批不改
    leaf_plans: list[_LeafPlan] = []
    comp_plans: list[_CompPlan] = []
    seen: set[str] = set()
    seen_rows: dict[tuple, str] = {}
    d = an.digits(doc.cost_breakdown_list) if doc.cost_breakdown_list is not None else None
    for e in edits:
        path = normalize_path(e.path)
        if e.component is not None:
            if d is None:
                raise EditError("底稿沒有單價分析表（CostBreakdownList），component 用不了")
            p = _plan_component(doc, e, idx, codes, d)
            keys = []
            if p.quantity is not None:
                keys.append(((p.acode, p.index, "quantity"), "數量"))
            if p.price is not None:
                keys.append((("general", p.code) if p.kind == an.GENERAL_KIND else (p.acode, p.index, "price"), "單價"))
            for key, what in keys:
                if key in seen_rows:
                    why = "一般工料的單價全案共用，只能給一次" if key[0] == "general" else "同一個分析的同一列"
                    raise EditError(f"{path} 的組成 {p.code} 的{what}跟 edits 裡「{seen_rows[key]}」那一筆改到同一個值（{why}），"
                                    "請合在同一筆")
                seen_rows[key] = f"{path} {p.code}"
            comp_plans.append(p)
            continue
        if path in seen:
            raise EditError(f"項次「{path}」在 edits 裡出現兩次，數量與單價請合在同一筆")
        seen.add(path)
        chain, it = resolve(doc, e.path, idx)
        name = _name(it)
        if it.children:
            raise EditError(
                f"{path} {name} 是母項，複價由子項加總，不能直接改。底下可改的葉項：{_listing(_leaves(chain, it), codes, idx)}"
            )
        kind = _kind(it)
        if kind == FORMULA_KIND or it.get("mml:math") is not None:
            raise EditError(f"{path} {name} 是公式項，金額由 PCCES 依公式算，改了也會在重新總計時被蓋掉；請在 PCCES 裡改公式")
        if kind not in EDITABLE_KINDS:
            raise EditError(f"{path} {name} 的 itemKind 是「{kind or '（空）'}」，這支工具只改 analysis、general、variablePrice 的葉項")
        if e.quantity is None and e.price is None:
            raise EditError(f"{path} {name}：quantity 與 price 至少給一個")
        if e.price is not None and _has_analysis(it, codes):
            acode = it.attrs.get("refItemCode", "").strip()
            copies = _copies(doc, acode)
            rows = f"這個分析的組成：{_component_rows(copies[0])}" if copies else "單價分析表沒有這個工項代碼"
            raise EditError(
                f"{path} {name} 有單價分析，單價由單價分析算出來，直接改 XML 的單價會在 PCCES 重新總計時被蓋回去。"
                f"要改單價就改它的單價分析：同一筆加 component（組成列的工料代碼）與那一列的新 quantity 或 price"
                f"{_example(path, copies[0]) if copies else ''}，工具會重算分析單價再更新詳細表。{rows}。{read_hint(path)}"
            )
        if e.quantity is not None:
            _check_number(e.quantity, f"{path} 的數量", q_dec, f"詳細表 quantityDisplayDecimal={q_dec}")
        if e.price is not None:
            _check_number(e.price, f"{path} 的單價", PRICE_MAX_DECIMALS, "PCCES 匯出檔的單價最多 2 位小數")
        for tag in ("Quantity", "Price", "Amount"):
            _node(it, tag, path)
        leaf_plans.append(_LeafPlan(path, chain, it, e.quantity, e.price))
    work = _plan_analyses(doc, comp_plans, d, idx) if comp_plans else {}

    # 小計列先照規則算一次底稿：規則重現得了底稿的列，改值後才有依據重算
    subs = _subtotals(doc)
    by_key: dict[str, list[Item]] = {}
    for _, it in dl.iter_items():
        by_key.setdefault(it.attrs.get("itemKey", "").strip(), []).append(it)
    before = _evaluate(subs, by_key)
    source = {id(s.item): s.item.decimal("Amount") for s in subs}

    analyses: list[AnalysisChange] = []
    resources: list[ResourceChange] = []
    if comp_plans:
        analyses, resources, leaf_price = _apply_components(doc, comp_plans, work, d, idx)
        by_id = {id(lp.item): lp for lp in leaf_plans}
        chains = _chains(doc)
        order0 = {id(it): n for n, (_, it) in enumerate(dl.iter_items())}
        for leaf_id in sorted(leaf_price, key=lambda k: order0[k]):
            lp = by_id.get(leaf_id)
            if lp is None:
                leaf = next(it for _, it in dl.iter_items() if id(it) == leaf_id)
                lp = _LeafPlan(idx.path(leaf), chains[leaf_id], leaf)
                leaf_plans.append(lp)
            lp.price, lp.via_analysis = leaf_price[leaf_id], True

    edited: list[ItemChange] = []
    ancestors: dict[int, tuple[int, Item]] = {}
    for lp in leaf_plans:
        it, path, chain = lp.item, lp.path, lp.chain
        q_old, p_old, a_old = it.decimal("Quantity"), it.decimal("Price"), it.decimal("Amount")
        q_new = lp.quantity if lp.quantity is not None else q_old
        p_new = lp.price if lp.price is not None else p_old
        amount = leaf_amount(q_new, p_new, p_dec, a_dec)
        if lp.quantity is not None:
            it.get("Quantity").text = fmt_decimal(lp.quantity)
        if lp.price is not None:
            it.get("Price").text = fmt_decimal(lp.price)
        it.get("Amount").text = fmt_decimal(amount)
        edited.append(ItemChange(
            path, _name(it), _kind(it),
            q_old, lp.quantity, p_old, lp.price,
            round_price(p_new, p_dec),
            a_old, amount, lp.via_analysis,
        ))
        for depth, anc in enumerate(chain):
            ancestors[id(anc)] = (depth, anc)

    order = {id(it): n for n, (_, it) in enumerate(dl.iter_items())}
    parents: list[tuple[int, AmountChange]] = []
    # 由深到淺：上層加總要用到下層剛改好的複價；小計子項不算，否則同一筆錢算兩次
    for depth, anc in sorted(ancestors.values(), key=lambda t: -t[0]):
        s = sum((c.decimal("Amount") or Decimal(0) for c in anc.children if _kind(c) != SUBTOTAL_KIND), Decimal(0))
        old = _set_sum(anc, _label(idx, anc), s)
        parents.append((order[id(anc)], AmountChange(idx.path(anc), _name(anc), old, s)))

    # 母項都改好了才算小計：有 MathML 的小計會引用母項（實案 小計(壹.一~壹.二) 引用壹.一、壹.二）
    after = _evaluate(subs, by_key)
    grand = dl.items[-1] if dl.items and _kind(dl.items[-1]) == SUBTOTAL_KIND else None
    subtotals: list[tuple[int, AmountChange]] = []
    stale: list[str] = []
    for sub in subs:
        it, b, a = sub.item, before[id(sub.item)], after[id(sub.item)]
        if isinstance(a, str) or isinstance(b, str):
            # 算不出來就分不出有沒有受影響，照抄底稿，交給 PCCES 重新總計
            stale.append(f"{_label(idx, it)}（{a if isinstance(a, str) else b}）")
            continue
        if a == b:
            continue
        if source[id(it)] != b:
            raise EditError(
                f"{_label(idx, it)} 在底稿是 {fmt_decimal(source[id(it)] or Decimal(0))}，照小計規則算是 {fmt_decimal(b)}，"
                "PCCES 怎麼算這一列沒有依據，這次的改動又會影響它，這支工具不處理；請在 PCCES 裡改。"
            )
        old = _set_sum(it, _label(idx, it), a)
        if it is not grand:
            subtotals.append((order[id(it)], AmountChange(idx.parent_path[id(it)], _name(it), old, a)))

    total = sum((i.decimal("Amount") or Decimal(0) for i in dl.items if _kind(i) != SUBTOTAL_KIND), Decimal(0))
    total_node = doc.grand_total.find("TotalAmount")
    if total_node is None:
        raise EditError("底稿的 GrandTotalInformation 沒有 TotalAmount，不像 PCCES 匯出的預算書")
    total_old = doc.total_amount
    total_node.text = fmt_decimal(total)

    chinese_done = False
    cn = doc.grand_total.find("TotalAmountChinese")
    if cn is not None and total >= 0 and total == total.to_integral_value():
        text = amount_chinese(int(total))
        if len(text) > CHINESE_MAX:
            raise EditError(f"總價國字「{text}」超過交換標準的 {CHINESE_MAX} 字")
        cn.text = text
        chinese_done = True

    formulas = _formula_items(doc, idx)
    return EditResult(
        edited=edited,
        parents=[c for _, c in sorted(parents, key=lambda t: t[0])],
        total_old=total_old,
        total_new=total,
        formula_items=formulas,
        quantity_changed=any(e.quantity is not None for e in edits),
        price_decimals=p_dec,
        not_updated=_not_updated(doc, formulas, chinese_done or cn is None, stale, analyses, resources),
        subtotals=[c for _, c in sorted(subtotals, key=lambda t: t[0])],
        analyses=analyses,
        resources=resources,
    )


# ---------- 寫檔 ----------


def _check_suffix(suffix: str, title: str) -> None:
    if re.search(r"[&<>\r\n\t]", suffix):
        # 寫出器會照 XML 規則跳脫，但 PCCES 的跳脫寫法沒驗過（兩份示範案例都沒有這些字）
        raise EditError("title_suffix 不能含 & < > 或換行、tab，例如改用「（PCX改值）」")
    if len(title + suffix) > TITLE_MAX:
        raise EditError(f"工程名稱加上 title_suffix 超過交換標準的 {TITLE_MAX} 字，請縮短後綴")


def _reserve(out_dir: Path, contract_no: str, day: date) -> Path:
    """檔名用 ASCII：之後要在 PCCES 的檔案對話框貼路徑，中文經剪貼簿容易貼錯。"""
    out_dir.mkdir(parents=True, exist_ok=True)
    stem = re.sub(r"[^A-Za-z0-9_-]+", "_", contract_no).strip("_") or "budget"
    for n in range(1, 1000):
        p = out_dir / f"{stem}_edit_{day:%Y%m%d}_{n:02d}.xml"
        try:
            with open(p, "xb"):  # 獨占建立：已有同名檔就換下一個號碼，絕不覆蓋
                pass
        except FileExistsError:
            continue
        return p
    raise EditError(f"{out_dir} 裡同一工程同一天已有 999 份輸出，請先清掉舊檔")


def write_edited(
    source: str | Path,
    edits: list[ItemEdit],
    out_dir: str | Path,
    *,
    title_suffix: str | None = None,
    created_date: date | None = None,
) -> WriteResult:
    """讀底稿 → 改值重算 → 寫進 `out_dir` 的新檔 → 讀回寫出檔做金額檢查。底稿不動。"""
    src = Path(source)
    doc = parse_document(src)
    source_problems = check_consistency(parse_etender(src))
    result = apply_edits(doc, edits)
    if title_suffix:
        _check_suffix(title_suffix, doc.title())
        doc.set_title(doc.title() + title_suffix)
    day = created_date or date.today()
    path = _reserve(Path(out_dir), doc.contract_no, day)
    try:
        write_document(doc, path, created_date=day)
    except BaseException:
        path.unlink(missing_ok=True)
        raise
    # 金額檢查讀寫出來的檔，不讀記憶體裡的模型：驗的是 PCCES 會拿到的東西
    back = parse_etender(path)
    output_problems = check_consistency(back)
    if back.total_amount != result.total_new:
        output_problems.append(f"讀回寫出檔的總價 {back.total_amount} ≠ 工具算的 {result.total_new}")
    if result.analyses:
        output_problems += analysis_problems(parse_document(path), [a.code for a in result.analyses])
    return WriteResult(path, doc.title(), doc.contract_no, result, source_problems, output_problems)


def analysis_problems(doc: ETenderDocument, acodes: list[str]) -> list[str]:
    """寫出檔裡這幾個分析：每一份照規則對得上、詳細表用到它的葉項單價＝分析單價。"""
    if doc.cost_breakdown_list is None:
        return [f"寫出檔沒有單價分析表，找不到 {'、'.join(acodes)}"]
    d = an.digits(doc.cost_breakdown_list)
    out: list[str] = []
    for acode in acodes:
        copies = _copies(doc, acode)
        if not copies:
            out.append(f"寫出檔的單價分析表沒有 {acode}")
            continue
        for w in copies:
            out += [f"單價分析 {acode}：{m}" for m in an.mismatches(w, d)]
        for _, it in doc.detail_list.iter_items():
            if not it.children and it.attrs.get("refItemCode", "").strip() == acode and it.decimal("Price") != copies[0].decimal("Price"):
                out.append(f"詳細表工項 {acode} {_name(it)} 的單價 {it.value('Price')} ≠ 單價分析 {copies[0].value('Price')}")
    return out
